<?php
$money = static fn(mixed $amount): string => $amount === null ? 'Não informado' : 'R$ ' . number_format((float)$amount, 2, ',', '.');
$safeExternal = static fn(string $url): bool => in_array(strtolower((string)parse_url($url, PHP_URL_SCHEME)), ['http', 'https'], true) && filter_var($url, FILTER_VALIDATE_URL) !== false;
?>
<header class="property-detail-header"><div><a href="/properties">← Imóveis</a><h1><?= $e($property['address'] ?: $property['title']) ?></h1><p><?= $e($property['code']) ?> · <?= $e($types[$property['type']] ?? ucfirst($property['type'])) ?> · <?= $e($statuses[$property['status']] ?? ucfirst($property['status'])) ?></p></div><a href="/properties/<?= $e((string)$property['id']) ?>/edit" role="button" class="outline">Editar imóvel</a></header>
<section class="property-detail-grid">
    <article><header><strong>Dados do imóvel</strong></header><dl>
        <dt>Intenção</dt><dd><?= $e($intentions[$property['intention'] ?? ''] ?? 'Não informada') ?></dd>
        <?php if (in_array($property['intention'] ?? '', ['venda','venda_locacao'], true)): ?><dt>Valor de venda</dt><dd><?= $e($money($property['sale_price'])) ?></dd><?php endif ?>
        <?php if (in_array($property['intention'] ?? '', ['locacao','venda_locacao'], true)): ?><dt>Valor de locação</dt><dd><?= $e($money($property['rent_price'])) ?></dd><?php endif ?>
        <dt>Pretensão</dt><dd><?= $e($aspirations[$property['aspiration'] ?? ''] ?? 'Não informada') ?></dd>
        <dt>Área construída</dt><dd><?= $property['built_area'] === null ? 'Não informada' : $e(number_format((float)$property['built_area'], 2, ',', '.')) . ' m²' ?></dd>
        <dt>Área do terreno</dt><dd><?= $property['land_area'] === null ? 'Não informada' : $e(number_format((float)$property['land_area'], 2, ',', '.')) . ' m²' ?></dd>
        <dt>Condomínio</dt><dd><?= $e($money($property['condominium_price'])) ?></dd><dt>IPTU</dt><dd><?= $e($money($property['iptu_price'])) ?></dd>
        <dt>Endereço</dt><dd><?= $e(implode(', ',array_filter([$property['address'],$property['neighborhood'],$property['city']]))) ?: 'Não informado' ?></dd>
        <dt>Localização</dt><dd><?php if ($safeExternal((string)($property['google_maps_url'] ?? ''))): ?><a href="<?= $e($property['google_maps_url']) ?>" target="_blank" rel="noopener noreferrer">Abrir no Google Maps <span aria-label="abre em nova aba">↗</span></a><?php else: ?>Não informado<?php endif ?></dd>
        <dt>Link do anúncio</dt><dd><?php if ($safeExternal((string)$property['listing_url'])): ?><a href="<?= $e($property['listing_url']) ?>" target="_blank" rel="noopener noreferrer"><?= $e($property['listing_url']) ?> <span aria-label="abre em nova aba">↗</span></a><?php else: ?>Não informado<?php endif ?></dd>
        <dt>Observações</dt><dd><?= nl2br($e($property['notes']??'Nenhuma')) ?></dd>
    </dl></article>
    <article><header><strong>Relacionar a leads</strong></header><form method="GET" action="/properties/<?= $e((string)$property['id']) ?>"><label>Buscar lead<input type="search" name="lead_q" value="<?= $e($leadSearch) ?>" placeholder="Nome, telefone ou e-mail"></label><button type="submit" class="secondary">Localizar leads</button></form>
    <?php if($leadSearch): ?><form method="POST" action="/properties/<?= $e((string)$property['id']) ?>/leads"><?= $csrfField ?><fieldset><?php foreach($leadOptions as $lead): ?><label><input type="checkbox" name="lead_ids[]" value="<?= $e((string)$lead['id']) ?>"> <?= $e($lead['name']) ?> <small><?= $e($lead['phone']??$lead['email']??'') ?></small></label><?php endforeach ?><?php if(!$leadOptions): ?><small>Nenhum lead encontrado.</small><?php endif ?></fieldset><label>Tipo de relação<select name="interest_type"><option value="interesse">Interesse</option><option value="visitado">Visitado</option><option value="proposta">Proposta</option></select></label><label>Observação deste vínculo<textarea name="notes" rows="2" maxlength="2000"></textarea></label><button type="submit">Vincular selecionados</button></form><?php endif ?></article>
</section>
<section><h2>Leads relacionados <small>(<?= $e((string)count($leads)) ?>)</small></h2><?php if(!$leads): ?><p style="color:var(--pico-muted-color)">Nenhum lead relacionado. Busque um lead acima para criar o primeiro vínculo.</p><?php else: ?><p class="properties-scroll-hint" id="related-leads-table-hint">Em telas estreitas, os dados de cada lead aparecem agrupados em um cartão.</p><figure class="properties-table-wrap" role="region" aria-label="Leads relacionados ao imóvel" aria-describedby="related-leads-table-hint" tabindex="0"><table class="properties-table property-records-table"><thead><tr><th scope="col">Lead</th><th scope="col">Telefone</th><th scope="col">Relação</th><th scope="col">Observação</th><th scope="col">Vinculado em</th><th scope="col">Ações</th></tr></thead><tbody><?php foreach($leads as $lead): ?><tr><td data-label="Lead"><a href="/leads/<?= $e((string)$lead['id']) ?>"><?= $e($lead['name']) ?></a></td><td data-label="Telefone"><?= $e($lead['phone']??'—') ?></td><td data-label="Relação"><?= $e($lead['interest_type']) ?></td><td data-label="Observação"><?= $e($lead['notes']??'—') ?></td><td data-label="Vinculado em"><?= $e($lead['associated_at']) ?></td><td data-label="Ações"><form method="POST" action="/properties/<?= $e((string)$property['id']) ?>/leads/<?= $e((string)$lead['id']) ?>/delete" onsubmit="return confirm('Remover este vínculo? A ação ficará registrada na auditoria.');" style="margin:0"><?= $csrfField ?><button type="submit" class="outline secondary properties-unlink-button">Desvincular</button></form></td></tr><?php endforeach ?></tbody></table></figure><?php endif ?></section>
